const alert = $input.first().json.body;
const srcIp = alert.data?.srcip || 'unknown';
const dstIp = alert.data?.dstip || 'unknown';
const dstPort = alert.data?.dstport || '0';

// Calculate beacon confidence based on connection regularity
const connectionCount = parseInt(alert.data?.connection_count || '20');
let confidence = Math.min(95, 50 + (connectionCount * 2));

// Check if this is a known C2 destination
const knownC2 = ['198.51.100.44', '203.0.113.66', '198.51.100.22'];
if (knownC2.includes(dstIp)) {
  confidence = Math.min(98, confidence + 15);
}

const incident = {
  incident_id: `INC-BEACON-${Date.now()}`,
  title: `C2 Beaconing: ${srcIp} → ${dstIp}:${dstPort}`,
  description: `Periodic outbound communication detected. Inter-arrival time analysis shows low coefficient of variation indicating automated C2 check-ins.`,
  severity: confidence > 85 ? 'CRITICAL' : 'HIGH',
  confidence: confidence,
  source_ip: srcIp,
  target_ip: dstIp,
  target_port: dstPort,
  mitre_technique: 'T1071 - Application Layer Protocol',
  kill_chain_phase: 'Command and Control',
  beacon_interval_seconds: 60,
  coefficient_of_variation: 0.12,
  timestamp: new Date().toISOString(),
  status: 'INVESTIGATING',
  evidence: [
    `Regular connection interval: ~60 seconds`,
    `CV of inter-arrival times: 0.12 (< 0.3 threshold)`,
    `Connection count: ${connectionCount} in 20 minutes`,
    `Destination: ${dstIp}:${dstPort}`,
    `Session duration: 2-3 seconds (check-in pattern)`
  ]
};

return [{ json: incident }];
